def check_n4_solutions(max_val=20):
    solutions = []

    # Iterate over initial pairs (x1, x2)
    for x1 in range(2, max_val + 1):
        for x2 in range(2, max_val + 1):

            # Step 1: Calculate x3
            numerator_x3 = x2**2 + 1
            denominator_x3 = x1 + 1

            if numerator_x3 % denominator_x3 == 0:
                x3_candidate = (numerator_x3 // denominator_x3) - 1

                # Check if x3 is a positive integer
                if x3_candidate >= 1:
                    x3 = x3_candidate

                    # Step 2: Calculate x4
                    numerator_x4 = x3**2 + 1
                    denominator_x4 = x2 + 1

                    if numerator_x4 % denominator_x4 == 0:
                        x4_candidate = (numerator_x4 // denominator_x4) - 1

                        # Check if x4 is a positive integer
                        if x4_candidate >= 1:
                            x4 = x4_candidate
                            solutions.append((x1, x2, x3, x4))
                            print(f"Found solution for n=4: ({x1}, {x2}, {x3}, {x4})")

    return solutions

# Search up to a reasonable limit, say 20 for both x1 and x2 initially.
